SELECT fn_cp_import_case('num-escroquerie-locative-fausse-annonce', '{"slug": "num-escroquerie-locative-fausse-annonce", "title": "Elle a versé deux mois de caution pour un logement qui n''existe pas", "theme_slug": "numerique", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 10 heures. Une jeune femme se présente au commissariat, désemparée, après avoir versé l''équivalent de deux mois de loyer à titre de caution pour un logement qu''elle avait trouvé sur une annonce en ligne, découvrant à son arrivée sur place que ce logement n''existe tout simplement pas ou appartient à une tout autre personne n''ayant jamais mis ce bien en location. Cette victime étudiante, désormais sans solution de logement immédiate et privée d''une somme d''argent conséquente au regard de ses ressources limitées, se trouve dans une situation d''urgence matérielle qui dépasse le seul préjudice financier habituellement associé à ce type d''escroquerie.\n\nCette double conséquence, financière et matérielle, nécessite une prise en charge qui articule le traitement classique de cette plainte avec une orientation pratique vers des solutions d''urgence pour son hébergement immédiat.\n\nCette situation impose de recueillir méthodiquement les éléments de cette escroquerie locative tout en orientant cette victime vers les solutions d''urgence disponibles, cette double exigence nécessitant de ne pas se limiter au seul aspect procédural de cette plainte.", "questions": [{"position": 1, "max_points": 5, "label": "Comment recueillez-vous méthodiquement les éléments de cette escroquerie locative ?", "hint": "Le recueil de cette plainte doit être méthodique malgré l''urgence matérielle de cette victime, ces éléments restant nécessaires pour la suite du traitement de cette affaire.", "perfect": "Je recueille avec précision l''ensemble des éléments de cette annonce frauduleuse, notamment la plateforme utilisée et le contenu exact de cette publication qui l''a convaincue de ce logement inexistant.\n\nJe recueille les modalités précises de ce versement de caution, notamment le moyen de paiement utilisé et les coordonnées communiquées par ce prétendu bailleur, ces éléments pouvant orienter utilement l''enquête.\n\nJe recueille l''ensemble des échanges qu''elle a pu conserver avec cet interlocuteur frauduleux, ces messages constituant des éléments de preuve précieux pour caractériser cette escroquerie.\n\nJe reste attentive à recueillir ces éléments avec méthode malgré son état de désarroi, cette rigueur restant nécessaire pour la suite du traitement de cette affaire.", "points": [{"position": 1, "label": "Recueillir précisément les éléments de cette annonce frauduleuse", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : plateforme et contenu de la publication.", "groups": [{"position": 1, "keywords": ["annonce recueillie", "plateforme identifiée", "contenu documenté"]}]}, {"position": 2, "label": "Recueillir les modalités précises du versement de la caution", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Moyen de paiement et coordonnées communiquées.", "groups": [{"position": 1, "keywords": ["modalités de versement", "moyen de paiement", "coordonnées communiquées"]}]}, {"position": 3, "label": "Recueillir l''ensemble des échanges conservés avec cet interlocuteur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Messages constituant des éléments de preuve précieux.", "groups": [{"position": 1, "keywords": ["échanges recueillis", "éléments de preuve", "interlocuteur frauduleux"]}]}, {"position": 4, "label": "Recueillir ces éléments avec méthode malgré son désarroi", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur nécessaire pour la suite du traitement.", "groups": [{"position": 1, "keywords": ["méthode malgré désarroi", "rigueur nécessaire", "traitement de l''affaire"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment orientez-vous cette victime vers des solutions d''urgence pour son hébergement immédiat ?", "hint": "Au-delà du seul traitement de la plainte, cette victime sans solution de logement mérite une orientation pratique vers des dispositifs d''urgence adaptés à sa situation immédiate.", "perfect": "Je reste attentive à sa situation d''urgence matérielle, cette absence de solution de logement immédiate constituant une conséquence pratique aussi préoccupante que le seul préjudice financier subi.\n\nJe l''oriente vers les dispositifs d''hébergement d''urgence disponibles, ces ressources pouvant lui apporter une solution pratique immédiate en complément du seul traitement de sa plainte.\n\nJe recueille des éléments sur ses ressources et son réseau de soutien éventuel, cette évaluation me permettant d''orienter au mieux vers les solutions les plus adaptées à sa situation spécifique.\n\nJe reste attentive à ne pas me limiter au seul traitement procédural de cette plainte, cette dimension pratique de son urgence méritant une attention réelle de ma part.", "points": [{"position": 1, "label": "Rester attentive à sa situation d''urgence matérielle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : conséquence pratique aussi préoccupante que financière.", "groups": [{"position": 1, "keywords": ["urgence matérielle", "absence de logement", "conséquence pratique"]}]}, {"position": 2, "label": "Orienter vers les dispositifs d''hébergement d''urgence disponibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Solution pratique complémentaire au traitement de la plainte.", "groups": [{"position": 1, "keywords": ["dispositifs d''urgence", "hébergement orienté", "solution pratique"]}]}, {"position": 3, "label": "Recueillir des éléments sur ses ressources et son réseau de soutien", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orientation vers les solutions les plus adaptées.", "groups": [{"position": 1, "keywords": ["ressources évaluées", "réseau de soutien", "solutions adaptées"]}]}, {"position": 4, "label": "Ne pas se limiter au seul traitement procédural de la plainte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Attention réelle à la dimension pratique de l''urgence.", "groups": [{"position": 1, "keywords": ["au-delà du procédural", "attention réelle", "dimension pratique"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment l''informez-vous des démarches complémentaires pour tenter de limiter son préjudice financier ?", "hint": "Au-delà du seul dépôt de plainte, des démarches complémentaires peuvent utilement compléter le traitement de cette escroquerie pour tenter de limiter ce préjudice financier.", "perfect": "Je l''oriente vers les démarches de contestation bancaire qu''elle pourrait entreprendre selon le mode de paiement utilisé pour ce versement de caution frauduleux.\n\nJe l''informe de l''utilité de signaler cette annonce frauduleuse à la plateforme concernée, cette démarche pouvant contribuer à protéger d''autres personnes en recherche de logement contre ce même mode opératoire.\n\nJe reste réaliste sur les chances effectives de récupération de cette somme, sans lui donner de faux espoirs disproportionnés compte tenu du caractère souvent difficile à retracer de ce type d''escroquerie.\n\nJe l''oriente vers des associations d''aide aux victimes qui pourraient l''accompagner dans les suites pratiques de cette épreuve, cette dimension complétant utilement le seul traitement de sa plainte.", "points": [{"position": 1, "label": "Orienter vers les démarches de contestation bancaire selon le paiement utilisé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : possibilité selon le mode de versement.", "groups": [{"position": 1, "keywords": ["contestation bancaire", "mode de paiement", "démarche possible"]}]}, {"position": 2, "label": "Informer du signalement de cette annonce à la plateforme concernée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Protection d''autres personnes contre ce mode opératoire.", "groups": [{"position": 1, "keywords": ["signalement à la plateforme", "autres victimes protégées", "mode opératoire signalé"]}]}, {"position": 3, "label": "Rester réaliste sur les chances effectives de récupération", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Pas de faux espoirs face à la difficulté du traçage.", "groups": [{"position": 1, "keywords": ["réalisme sur la récupération", "pas de faux espoirs", "traçage difficile"]}]}, {"position": 4, "label": "Orienter vers des associations d''aide aux victimes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Accompagnement complétant le traitement de la plainte.", "groups": [{"position": 1, "keywords": ["associations d''aide", "accompagnement complémentaire", "suites pratiques"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('num-compte-pirate-envoi-messages-proches', '{"slug": "num-compte-pirate-envoi-messages-proches", "title": "Ses contacts ont reçu des demandes d''argent en son nom", "theme_slug": "numerique", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 15 heures. Un homme se présente au commissariat, alarmé, après avoir découvert que son compte de messagerie a été piraté et utilisé pour envoyer à l''ensemble de ses contacts personnels et professionnels des demandes d''argent urgentes présentées comme émanant de lui-même, cette propagation touchant potentiellement de nombreuses victimes supplémentaires parmi ses proches qui pourraient être trompés par cette usurpation de son identité. Cette diffusion en cours vers l''ensemble de son carnet de contacts constitue une urgence particulière puisque chaque minute qui passe augmente le risque que certains de ses proches, de bonne foi, répondent favorablement à ces demandes frauduleuses.\n\nCette situation, où le préjudice ne se limite pas à la seule victime initiale mais s''étend potentiellement à l''ensemble de son réseau de contacts, nécessite une action rapide pour alerter ces victimes potentielles avant qu''elles ne soient elles-mêmes trompées par cette usurpation.\n\nCette configuration impose de faire alerter sans délai l''ensemble des contacts concernés tout en sécurisant ce compte piraté, cette double urgence nécessitant une action rapide sur ces deux fronts complémentaires.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous alerter sans délai l''ensemble des contacts potentiellement visés par cette propagation ?", "hint": "L''urgence de cette alerte est cruciale car chaque minute augmente le risque que des proches de bonne foi répondent favorablement à ces demandes frauduleuses.", "perfect": "Je l''encourage à alerter sans délai l''ensemble de ses contacts par tout autre moyen de communication non compromis, cette rapidité étant essentielle pour limiter le nombre de victimes supplémentaires.\n\nJe lui conseille de publier une alerte visible sur ses autres canaux de communication disponibles, cette diffusion large pouvant toucher rapidement une grande partie de son réseau de contacts concernés.\n\nJe reste attentive à l''urgence de cette situation, chaque minute supplémentaire de propagation augmentant le risque que des proches de bonne foi ne répondent favorablement à ces demandes frauduleuses.\n\nJe lui suggère de contacter en priorité les personnes les plus susceptibles de répondre rapidement à une demande d''argent, comme des proches ou collègues avec lesquels il entretient une relation de confiance particulière.", "points": [{"position": 1, "label": "Encourager à alerter sans délai par un moyen de communication non compromis", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rapidité limitant les victimes supplémentaires.", "groups": [{"position": 1, "keywords": ["alerte sans délai", "moyen non compromis", "victimes limitées"]}]}, {"position": 2, "label": "Conseiller de publier une alerte visible sur d''autres canaux", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Diffusion large touchant rapidement le réseau de contacts.", "groups": [{"position": 1, "keywords": ["alerte visible", "diffusion large", "réseau touché"]}]}, {"position": 3, "label": "Rester attentive à l''urgence de cette propagation continue", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Chaque minute augmentant le risque pour les proches.", "groups": [{"position": 1, "keywords": ["urgence de propagation", "risque croissant", "proches de bonne foi"]}]}, {"position": 4, "label": "Suggérer de contacter en priorité les personnes les plus susceptibles de répondre", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Relations de confiance particulière.", "groups": [{"position": 1, "keywords": ["priorité de contact", "relation de confiance", "réponse rapide probable"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment sécurisez-vous ce compte piraté pour faire cesser cette propagation à la source ?", "hint": "Au-delà de la seule alerte des contacts, la sécurisation du compte lui-même reste nécessaire pour faire cesser cette propagation à sa racine.", "perfect": "Je lui conseille de tenter de reprendre le contrôle de ce compte piraté sans délai, cette récupération technique restant la solution la plus efficace pour faire cesser cette diffusion frauduleuse à sa source.\n\nJe l''oriente vers les procédures de récupération proposées par le service concerné si la reprise directe du contrôle s''avère impossible, ces démarches techniques pouvant compléter utilement ses propres tentatives.\n\nJe lui conseille de modifier immédiatement ses autres mots de passe s''il utilisait des identifiants similaires sur d''autres services, cette précaution évitant une propagation de cette compromission à d''autres comptes.\n\nJe reste attentive à l''accompagner dans ces démarches techniques si son état de stress rend cette organisation difficile, cette assistance pratique restant appropriée face à l''urgence de la situation.", "points": [{"position": 1, "label": "Conseiller de tenter de reprendre le contrôle du compte sans délai", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : solution efficace pour cesser la diffusion à la source.", "groups": [{"position": 1, "keywords": ["contrôle repris", "diffusion cessée", "source traitée"]}]}, {"position": 2, "label": "Orienter vers les procédures de récupération du service concerné", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Démarches complétant les tentatives personnelles.", "groups": [{"position": 1, "keywords": ["procédures de récupération", "service concerné", "démarches complémentaires"]}]}, {"position": 3, "label": "Conseiller de modifier les mots de passe similaires sur d''autres services", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une propagation de la compromission.", "groups": [{"position": 1, "keywords": ["mots de passe modifiés", "propagation évitée", "autres comptes protégés"]}]}, {"position": 4, "label": "Accompagner dans ces démarches techniques face au stress", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Assistance pratique appropriée face à l''urgence.", "groups": [{"position": 1, "keywords": ["accompagnement pratique", "stress pris en compte", "assistance appropriée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment recueillez-vous les éléments nécessaires pour la suite du traitement de ce piratage ?", "hint": "Au-delà de l''urgence immédiate, un recueil méthodique reste nécessaire pour la suite du traitement de cette affaire de piratage informatique.", "perfect": "Je recueille avec précision le contenu exact des messages frauduleux envoyés depuis son compte, cette documentation étant nécessaire pour caractériser précisément cette escroquerie par usurpation.\n\nJe l''interroge sur l''origine possible de ce piratage, notamment un éventuel message suspect qu''il aurait pu ouvrir récemment, ces éléments pouvant orienter utilement l''enquête sur les circonstances de cette intrusion.\n\nJe recueille si possible les informations sur d''éventuels contacts ayant déjà répondu à ces demandes frauduleuses, ces victimes supplémentaires méritant d''être identifiées et informées de cette réalité.\n\nJe l''informe des suites de cette procédure, notamment sur l''importance de rassurer ses contacts une fois cette situation résolue pour restaurer la confiance dans ses communications futures.", "points": [{"position": 1, "label": "Recueillir précisément le contenu des messages frauduleux envoyés", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : documentation caractérisant l''escroquerie.", "groups": [{"position": 1, "keywords": ["contenu recueilli", "messages frauduleux", "escroquerie caractérisée"]}]}, {"position": 2, "label": "Interroger sur l''origine possible de ce piratage", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Message suspect ouvert récemment orientant l''enquête.", "groups": [{"position": 1, "keywords": ["origine interrogée", "message suspect", "enquête orientée"]}]}, {"position": 3, "label": "Recueillir les informations sur d''éventuels contacts ayant déjà répondu", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Victimes supplémentaires à identifier et informer.", "groups": [{"position": 1, "keywords": ["contacts ayant répondu", "victimes identifiées", "information nécessaire"]}]}, {"position": 4, "label": "Informer de l''importance de rassurer ses contacts une fois résolu", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Restaurer la confiance dans les communications futures.", "groups": [{"position": 1, "keywords": ["contacts rassurés", "confiance restaurée", "communications futures"]}]}]}]}'::jsonb);
